+            } catch (Exception e) {
+                System.err.println("Error in listener during complete: " + e.getMessage());
+            }
+        }
+    }
+
+    @Override
+    public void onComputationError(Exception exception) {
+        for (ComputationListener listener : listeners) {
+            try {
+                listener.onComputationError(exception);
